import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Color,
  } = ctx.THREE;

  const root = new Group();
  const timelines = [];
  const ownedResources = [];
  const pendingTextures = [];

  root.userData.handlers = {};

  const cardWidth = 2.56;
  const cardHeight = 1.6;

  const backingMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
  });
  const backingGeometry = new BoxGeometry(cardWidth, cardHeight, 0.08);
  const backing = new Mesh(backingGeometry, backingMaterial);
  backing.position.z = -0.06;
  root.add(backing);
  ownedResources.push(backingGeometry, backingMaterial);

  const surfaceMaterial = new MeshBasicNodeMaterial();
  const gradientPosition = smoothstep(0.04, 0.96, uv().y);
  surfaceMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    gradientPosition,
  );

  const surfaceGeometry = new PlaneGeometry(cardWidth, cardHeight);
  const surface = new Mesh(surfaceGeometry, surfaceMaterial);
  surface.position.z = 0.01;
  root.add(surface);
  ownedResources.push(surfaceGeometry, surfaceMaterial);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
  });
  const accentGeometry = new BoxGeometry(0.055, 0.82, 0.018);
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-1.08, -0.02, 0.045);
  root.add(accent);
  ownedResources.push(accentGeometry, accentMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textOffset = 0;

  for (const item of items) {
    const text = typeof item === 'string' ? item : item?.text;
    if (typeof text !== 'string') continue;

    const typography = typeof item === 'object' ? item.typography ?? {} : {};
    const textObject = ctx.fontAtlas.createText(text, {
      fontSize: typography.fontSize ?? 39,
      color: '#e8ecf2',
      align: typography.align ?? 'left',
      maxWidthPx: typography.maxWidthPx,
      letterSpacingPx: typography.letterSpacingPx,
    });

    textObject.position.set(-0.88, 0.02 - textOffset, 0.07);
    root.add(textObject);
    textOffset += 0.32;
  }

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    const texturePromise = ctx.textureLoader.loadTexture(imageUrl);
    pendingTextures.push(texturePromise);

    texturePromise.then((texture) => {
      texture.repeat.set(1, 1);
      texture.offset.set(0, 0);
      texture.needsUpdate = true;

      if ('colorSpace' in texture && ctx.THREE.SRGBColorSpace) {
        texture.colorSpace = ctx.THREE.SRGBColorSpace;
      }

      surfaceMaterial.map = texture;
      surfaceMaterial.needsUpdate = true;
      ownedResources.push(texture);
    }).catch(() => {});
  }

  root.onBeforeRender = (_renderer, _scene, camera) => {
    root.quaternion.copy(camera.quaternion);
  };

  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    for (const resource of ownedResources) {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    }

    root.traverse((object) => {
      if (object !== root && object.userData?.cleanup && object.userData.cleanup !== root.userData.cleanup) {
        object.userData.cleanup();
      }
    });

    root.clear();
  };

  return root;
}
